import sys
from collections import deque

def main():
    input_data = sys.stdin.read().split()
    if not input_data:
        return

    iterator = iter(input_data)
    n = int(next(iterator))
    k = int(next(iterator))

    adj = [[] for _ in range(n + 1)]
    parents = [0] * (n + 1)

    for i in range(2, n + 1):
        p = int(next(iterator))
        parents[i] = p
        adj[p].append(i)

    leaves = []
    depths = [0] * (n + 1)

    q = deque([1])
    depths[1] = 0

    while q:
        u = q.popleft()
        if adj[u]:
            for v in adj[u]:
                depths[v] = depths[u] + 1
                q.append(v)
        else:
            if u != 1:
                leaves.append(u)

    if not leaves:
        print(0)
        return

    def get_ancestor(u, steps):
        while steps > 0:
            u = parents[u]
            steps -= 1
        return u

    min_depths = {}

    for leaf in leaves:
        d = depths[leaf]
        if d <= k:
            min_depths[leaf] = 0
        else:
            anc = get_ancestor(leaf, k)
            min_depths[leaf] = depths[anc]

    sorted_leaves = sorted(leaves, key=lambda x: min_depths[x])

    max_visited = 0
    current_min_depth = float('inf')

    for leaf in sorted_leaves:
        req_depth = min_depths[leaf]
        if req_depth >= current_min_depth:
            continue
        current_min_depth = req_depth
        max_visited += 1

    print(max_visited)

if __name__ == "__main__":
    main()
